const DAYS_AGO = 7;
const usernames = [...new Set($input.all().map(item => String(item.json.username || '').trim()).filter(Boolean))];
if (usernames.length === 0) { return [{ json: { should_continue: false, scheduler_alert_type: 'NO_TRACKED_USERS', message: 'Scheduled tracking ran with no tracked users configured.' } }]; }
const startDate = new Date();
startDate.setUTCDate(startDate.getUTCDate() - DAYS_AGO);
return [{ json: { should_continue: true, query: usernames.map(username => `from:${username}`).join(' OR '), start_time: startDate.toISOString(), usernames, user_count: usernames.length } }];

// T3 fallbacks. These are the pre-T3 constants: if a post's client cannot be
// resolved the post behaves exactly as it did before T3 rather than alerting on
// everything. It is then reported by Build Negative Alert Notification.
const DEFAULT_MIN_REPLIES = 10;
const DEFAULT_NEGATIVE_THRESHOLD = 0.5;

const state = $('Advance Post Suppression State').first()?.json || {};
const rawBlocked = state.blocked_post_ids || [];

// Author identity now comes from Tracked Users, so the posts query no longer
// pays for expansions=author_id / includes.users on every run.
const trackedByUserId = new Map(
  $('Get Tracked Users').all().map(item => [String(item.json.user_id || ''), item.json || {}])
);

let blockedIds = [];
if (Array.isArray(rawBlocked)) {
  blockedIds = rawBlocked;
} else if (typeof rawBlocked === 'string') {
  blockedIds = rawBlocked
    .replace(/^\{/, '')
    .replace(/\}$/, '')
    .split(',')
    .map(value => value.replace(/^"|"$/g, '').trim())
    .filter(Boolean);
}

const blocked = new Set(blockedIds.map(String));
return $input.all()
  .filter(item => !blocked.has(String(item.json.id || '')))
  .map(item => {
    const tracked = trackedByUserId.get(String(item.json.author_id)) || {};
    const username = String(tracked.username || '').trim();
    const name = String(tracked.display_name || '').trim();

    return {
      json: {
        ...item.json,
        author_username: username,
        author_name: name,
        post_author: username ? `@${username}` : (name || String(item.json.author_id || 'unknown')),
        // T3: the owning client rides along with the post from here on, so the
        // reply-count gate, the sentiment gate and the alert fan-out can each be
        // decided per client instead of against a global constant.
        client_id: String(tracked.client_id || ''),
        client_slug: String(tracked.client_slug || ''),
        client_name: String(tracked.client_name || ''),
        client_min_replies: Number.isFinite(Number(tracked.client_min_replies))
          ? Number(tracked.client_min_replies)
          : DEFAULT_MIN_REPLIES,
        client_negative_threshold: Number.isFinite(Number(tracked.client_negative_threshold))
          ? Number(tracked.client_negative_threshold)
          : DEFAULT_NEGATIVE_THRESHOLD,
      },
    };
  });

const LOOKBACK_DAYS = 7;
const MAX_QUERY_CHARS = 1000;              // X caps search/all queries at 1024
const MAX_CONVERSATIONS_PER_CHUNK = 15;    // limits-and-capacity.md 7.1
const OVERLAP_MINUTES = 10;                // tolerate X indexing lag; reply_id dedupes

const conversationIds = [...new Set(
  $input.all()
    .map(item => String(item.json.conversation_id || '').trim())
    .filter(Boolean)
)];

if (conversationIds.length === 0) {
  return [];
}

const runState = $('Get Run State').first()?.json || {};
const runStartedAt = runState.run_started_at ? new Date(runState.run_started_at) : new Date();
const lastRun = runState.last_successful_run_at ? new Date(runState.last_successful_run_at) : null;

let startTime;
let isBackfill = false;
if (lastRun && !Number.isNaN(lastRun.getTime())) {
  startTime = new Date(lastRun.getTime() - OVERLAP_MINUTES * 60000);
} else {
  // First run after deploy: one full-window pass backfills the stored counts.
  isBackfill = true;
  startTime = new Date(runStartedAt.getTime() - LOOKBACK_DAYS * 86400000);
}

// X rejects a start_time that is too close to now.
const newestAllowed = new Date(Date.now() - 30000);
if (startTime.getTime() > newestAllowed.getTime()) {
  startTime = newestAllowed;
}

const clause = id => `(conversation_id:${id} is:reply)`;

// Chunk by measuring the assembled string, not by counting items.
const chunks = [];
let current = [];
for (const id of conversationIds) {
  const candidate = [...current, id];
  const assembled = candidate.map(clause).join(' OR ');
  const tooLong = assembled.length > MAX_QUERY_CHARS;
  const tooMany = candidate.length > MAX_CONVERSATIONS_PER_CHUNK;
  if (current.length > 0 && (tooLong || tooMany)) {
    chunks.push(current);
    current = [id];
  } else {
    current = candidate;
  }
}
if (current.length > 0) {
  chunks.push(current);
}

return chunks.map((ids, index) => ({
  json: {
    query: ids.map(clause).join(' OR '),
    start_time: startTime.toISOString(),
    run_started_at: runStartedAt.toISOString(),
    is_backfill: isBackfill,
    conversation_ids: ids,
    conversation_count: ids.length,
    chunk_index: index,
    chunk_count: chunks.length,
  },
}));

const MAX_IMAGES_PER_REPLY = 4;

const analyzedRow = $('Get Analyzed Reply Ids').first()?.json || {};
let analyzedIds = analyzedRow.analyzed_reply_ids || [];
if (typeof analyzedIds === 'string') {
  // Postgres text[] can arrive as a literal '{a,b,c}'.
  analyzedIds = analyzedIds
    .replace(/^\{/, '')
    .replace(/\}$/, '')
    .split(',')
    .map(value => value.replace(/^"|"$/g, '').trim())
    .filter(Boolean);
}
const alreadyAnalyzed = new Set((Array.isArray(analyzedIds) ? analyzedIds : []).map(String));

const postsByConversation = new Map(
  $('Keep Posts With 10+ Replies').all().map(item => [
    String(item.json.conversation_id),
    {
      postId: item.json.id,
      postText: item.json.text,
      userId: item.json.author_id,
      postAuthor: item.json.post_author || (item.json.author_username ? `@${item.json.author_username}` : String(item.json.author_id || 'unknown')),
      authorUsername: item.json.author_username || '',
      authorName: item.json.author_name || '',
      totalReplyCount: Number(item.json.public_metrics?.reply_count ?? 0),
      replies: [],
    },
  ])
);

const replyPages = $('Get Replies').all();

const seen = new Set();
let newReplyCount = 0;
let fetchedReplyCount = 0;

// Replies carrying images or a video thumbnail. Relabelled downstream by a per-reply
// multimodal call, because text-only analysis cannot see an image-only insult.
const mediaReplies = [];
let unresolvedMediaKeys = 0;

for (const group of replyPages) {
  // media_keys resolve against this page's includes.media block.
  const includes = group.json.includes || {};
  const mediaByKey = new Map();
  for (const m of (includes.media || [])) {
    mediaByKey.set(String(m.media_key), m);
  }

  for (const reply of group.json.data || []) {
    fetchedReplyCount += 1;
    const post = postsByConversation.get(String(reply.conversation_id));
    if (!post || !reply.id) continue;

    const replyId = String(reply.id);
    // Skip replies scored in an earlier pass, and duplicates across chunks/overlap/pages.
    if (alreadyAnalyzed.has(replyId) || seen.has(replyId)) continue;
    seen.add(replyId);

    const text = String(reply.text || '').replace(/\s+/g, ' ').trim();
    post.replies.push({
      id: replyId,
      text,
    });
    newReplyCount += 1;

    const declaredKeys = (reply.attachments && reply.attachments.media_keys) ? reply.attachments.media_keys : [];
    const imageUrls = [];
    for (const key of declaredKeys) {
      const m = mediaByKey.get(String(key));
      if (!m) { unresolvedMediaKeys += 1; continue; }
      // Photos expose url. Video and animated_gif expose only a thumbnail.
      const url = m.url || m.preview_image_url || '';
      if (url) imageUrls.push(url);
    }

    if (imageUrls.length > 0) {
      mediaReplies.push({
        reply_id: replyId,
        post_id: String(post.postId || ''),
        postText: String(post.postText || ''),
        replyText: text,
        imageUrls: imageUrls.slice(0, MAX_IMAGES_PER_REPLY),
      });
    }
  }
}

// Page-cap detection. Pagination stops either because a page carried no next_token
// (complete) or because maxRequests was reached (truncated). Group pages back to the
// chunk that produced them and check whether that chunk's LAST page still had a token.
// A silent cap here would look identical to "there was nothing more", and under
// incremental fetching the missed replies are never requested again.
function lastPageStillHasToken(pages) {
  const byChunk = new Map();
  pages.forEach((page, index) => {
    let key = 'unknown';
    const paired = page.pairedItem;
    if (typeof paired === 'number') key = String(paired);
    else if (paired && typeof paired === 'object' && paired.item !== undefined) key = String(paired.item);
    if (!byChunk.has(key)) byChunk.set(key, []);
    byChunk.get(key).push(page);
  });
  for (const group of byChunk.values()) {
    const last = group[group.length - 1];
    if (last?.json?.meta?.next_token) return true;
  }
  return false;
}

const repliesTruncated = lastPageStillHasToken(replyPages);

let postsTruncated = false;
let postPageCount = 0;
try {
  const postPages = $('Get posts of tracked users').all();
  postPageCount = postPages.length;
  postsTruncated = lastPageStillHasToken(postPages);
} catch (e) {
  // posts node output unavailable; leave defaults
}

// T3: which client owns each post, and its thresholds. Built as a separate map
// and deliberately kept OUT of `results`/`text`, because `text` is the OpenAI
// prompt payload -- tenancy ids have no business in it, and adding them would
// change the prompt, its cost, and the model's input for no gain.
const post_client_map = {};
for (const item of $('Keep Posts With 10+ Replies').all()) {
  const row = item.json || {};
  const postId = String(row.id || '');
  if (!postId) continue;
  post_client_map[postId] = {
    client_id: String(row.client_id || ''),
    client_slug: String(row.client_slug || ''),
    client_name: String(row.client_name || ''),
    min_replies: Number(row.client_min_replies ?? 10),
    negative_threshold: Number(row.client_negative_threshold ?? 0.5),
  };
}

const allPosts = [...postsByConversation.values()];
// Only posts with something new go to OpenAI.
const results = allPosts.filter(post => post.replies.length > 0);

return [{
  json: {
    has_new_replies: newReplyCount > 0,
    new_reply_count: newReplyCount,
    fetched_reply_count: fetchedReplyCount,
    reply_page_count: replyPages.length,
    post_page_count: postPageCount,
    replies_truncated: repliesTruncated,
    posts_truncated: postsTruncated,
    fetch_truncated: repliesTruncated || postsTruncated,
    media_reply_count: mediaReplies.length,
    unresolved_media_keys: unresolvedMediaKeys,
    media_replies: mediaReplies,
    post_client_map,
    candidate_post_ids: allPosts.map(post => String(post.postId || '')).filter(Boolean),
    text: JSON.stringify({ results }),
  },
}];

// T3: the alert threshold is per client now. This constant survives only as the
// fallback for a post whose client did not resolve, and equals the pre-T3 value.
const DEFAULT_ALERT_THRESHOLD = 0.5;

function parseResults(item) {
  const candidates = [
    item.json?.output?.[0]?.content?.[0]?.text,
    item.json?.output,
    item.json?.text,
  ];

  for (const candidate of candidates) {
    let value = candidate;
    if (typeof value === 'string') {
      try {
        value = JSON.parse(value);
      } catch {
        continue;
      }
    }

    if (Array.isArray(value?.results)) {
      return value.results;
    }
  }

  throw new Error('OpenAI response did not contain a results array.');
}

function parseInputPosts() {
  const raw = $('Attach replies to posts').first()?.json?.text;
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed.results) ? parsed.results : [];
  } catch {
    return [];
  }
}

const inputPostsById = new Map(
  parseInputPosts().map(post => [String(post.postId || ''), post])
);

// T3: per-post client thresholds, carried alongside the post rather than inside
// the model payload. See Attach replies to posts.
const clientByPostId = $('Attach replies to posts').first()?.json?.post_client_map || {};

// Counts from replies scored in earlier passes.
const storedByPostId = new Map(
  $('Get Stored Post Counts').all().map(item => {
    const row = item.json || {};
    return [String(row.post_id || ''), {
      analyzed: Number(row.stored_analyzed || 0),
      negative: Number(row.stored_negative || 0),
      positive: Number(row.stored_positive || 0),
      neutral: Number(row.stored_neutral || 0),
    }];
  })
);

// Read the media-corrected labels, not the raw batched output: replies carrying an
// image are relabelled by a per-reply multimodal call in Apply Media Sentiment.
const posts = $('Apply Media Sentiment').all().flatMap(item =>
  parseResults(item).map(post => {
    const postId = String(post.postId || '');
    const metadata = inputPostsById.get(postId) || {};
    const replies = Array.isArray(post.replies) ? post.replies : [];

    const fresh = { positive: 0, neutral: 0, negative: 0 };
    for (const reply of replies) {
      const sentiment = String(reply.sentiment || '').toLowerCase();
      if (Object.prototype.hasOwnProperty.call(fresh, sentiment)) {
        fresh[sentiment] += 1;
      }
    }

    const stored = storedByPostId.get(postId) || { analyzed: 0, negative: 0, positive: 0, neutral: 0 };
    const client = clientByPostId[postId] || {};
    const clientThreshold = Number(client.negative_threshold);
    const alert_threshold = Number.isFinite(clientThreshold) ? clientThreshold : DEFAULT_ALERT_THRESHOLD;

    // The ratio is (stored + new) / (stored + new), never this run's slice alone.
    const new_analyzed_count = replies.length;
    const analyzed_count = stored.analyzed + new_analyzed_count;
    const negative_count = stored.negative + fresh.negative;
    const positive_count = stored.positive + fresh.positive;
    const neutral_count = stored.neutral + fresh.neutral;
    const negative_ratio = analyzed_count > 0 ? negative_count / analyzed_count : 0;

    const total_reply_count = Number(metadata.totalReplyCount ?? analyzed_count);

    let overall_tag = 'Neutral';
    if (positive_count > neutral_count && positive_count > negative_count) {
      overall_tag = 'Positive';
    } else if (negative_count > neutral_count && negative_count > positive_count) {
      overall_tag = 'Negative';
    }

    return {
      postId: post.postId,
      postText: post.postText,
      userId: post.userId || metadata.userId,
      postAuthor: metadata.postAuthor || post.postAuthor || String(post.userId || metadata.userId || 'unknown'),
      authorUsername: metadata.authorUsername || post.authorUsername || '',
      authorName: metadata.authorName || post.authorName || '',
      replies,
      new_analyzed_count,
      new_negative_count: fresh.negative,
      stored_analyzed_count: stored.analyzed,
      stored_negative_count: stored.negative,
      comments_count: analyzed_count,
      analyzed_count,
      total_reply_count,
      positive_count,
      neutral_count,
      negative_count,
      negative_ratio,
      negative_percentage: Math.round(negative_ratio * 100),
      overall_tag,
      // T3: the owning client travels with the post so the alert fan-out can route
      // on it without re-querying, and so execution data shows who a post was for.
      client_id: String(client.client_id || ''),
      client_slug: String(client.client_slug || ''),
      client_name: String(client.client_name || ''),
      alert_threshold,
      // Storage is no longer gated on the threshold - only alerting is.
      alert_now: negative_ratio >= alert_threshold,
    };
  })
);

return [{ json: { posts } }];

const allPosts = $("Split Out Reply Analysis").all();

const allReplies = allPosts.flatMap(post => {
  const replies = post.json.replies || [];
  return replies.map(reply => ({
    ...reply,
    postId: post.json.postId,
    postText: post.json.postText
  }));
});

return allReplies.map(reply => ({ json: reply }));

// Storage is no longer gated on the threshold, so the alert gate lives here.
//
// T3: alerts are routed per client. A post reaches exactly the chats that are
// active, alert-receiving members of the client that owns it, and never the whole
// recipient table. Input is Get Alert Recipients, not the retired Telegram Users.
const posts = $('Split Out Reply Analysis').all()
  .map(item => item.json || {})
  .filter(post => post.alert_now);

const replyCountsByPostId = new Map(
  $('Get Reply Status Counts').all().map(item => {
    const row = item.json || {};
    return [String(row.post_id || ''), {
      hiddenNegative: Number(row.hidden_negative_replies_count || 0),
      nonHiddenNegative: Number(row.non_hidden_negative_replies_count || 0),
    }];
  })
);

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

if (posts.length === 0) { return []; }

// Recipients grouped by client. Get Alert Recipients LEFT JOINs, so a client with
// no eligible member arrives as a row with a null chat_id -- that is how a
// misconfigured client is detected instead of silently skipped.
//
// Dedupe by (client, chat) defensively. The query runs executeOnce, but a repeated
// pair must never become a repeated alert.
const recipientsByClient = new Map();
const clientNameById = new Map();
const seenRecipients = new Set();
for (const item of $input.all()) {
  const row = item.json || {};
  const clientId = String(row.client_id || '');
  if (!clientId) { continue; }
  if (!recipientsByClient.has(clientId)) { recipientsByClient.set(clientId, []); }
  if (row.client_name) { clientNameById.set(clientId, String(row.client_name)); }

  const chatId = String(row.chat_id || '');
  if (!chatId) { continue; }
  const key = clientId + '|' + chatId;
  if (seenRecipients.has(key)) { continue; }
  seenRecipients.add(key);
  recipientsByClient.get(clientId).push({
    chat_id: chatId,
    label: String(row.label || ''),
    role: String(row.role || ''),
  });
}

// Posts grouped by owner. An empty client_id means the owner did not resolve
// upstream; such a post is reported to the developer chat, never broadcast.
const postsByClient = new Map();
for (const post of posts) {
  const clientId = String(post.client_id || '');
  if (!postsByClient.has(clientId)) { postsByClient.set(clientId, []); }
  postsByClient.get(clientId).push(post);
}

function describeClient(clientId) {
  if (!clientId) { return 'an unresolved client (the post owner did not resolve)'; }
  const name = clientNameById.get(clientId);
  return name ? name + ' (' + clientId + ')' : clientId;
}

function buildAlert(clientId, recipient, post, index) {
  const postId = String(post.postId || '');
  const counts = replyCountsByPostId.get(postId) || {};
  const text = escapeHtml(post.postText || '');
  const author = escapeHtml(post.postAuthor || post.authorUsername || post.userId || 'unknown');
  const totalReplies = Number(post.total_reply_count ?? post.comments_count ?? 0);
  const analyzedReplies = Number(post.analyzed_count ?? post.comments_count ?? 0);
  const negativeCount = Number(post.negative_count ?? 0);
  const hiddenNegativeReplies = Number(counts.hiddenNegative ?? 0);
  const nonHiddenNegativeReplies = Number(counts.nonHiddenNegative ?? Math.max(negativeCount - hiddenNegativeReplies, 0));
  const negativePercentage = post.negative_percentage ?? 0;
  const overall = escapeHtml(post.overall_tag || 'Negative');
  const tweetUrl = 'https://x.com/i/web/status/' + postId;
  const message = [
    '<b>XMonitor Scheduled Post Alert</b>',
    '',
    '<b>Post ' + (index + 1) + '</b>',
    'Author: ' + author,
    'Post ID: <code>' + postId + '</code>',
    'Link: ' + tweetUrl,
    '',
    '<b>Key Metrics</b>',
    'Total replies: ' + totalReplies,
    'Analyzed replies: ' + analyzedReplies,
    'Negative replies: ' + negativeCount,
    'Hidden negative replies: ' + hiddenNegativeReplies,
    'Visible negative replies: ' + nonHiddenNegativeReplies,
    'Negative sentiment: ' + negativePercentage + '%',
    'Overall sentiment: ' + overall,
    '',
    '<b>Post Text</b>',
    text || '(empty)',
  ].join('\n');
  return { json: {
    notify_ready: true,
    chat_id: recipient.chat_id,
    client_id: clientId,
    post_id: postId,
    message,
    snooze_button_text: 'Snooze',
    snooze_callback_data: 'snooze:' + postId,
    ignore_button_text: 'Ignore',
    ignore_callback_data: 'ignore:' + postId,
    hide_button_text: 'Hide replies for Post #' + (index + 1),
    hide_callback_data: 'hide_replies:' + postId,
  } };
}

const out = [];
for (const [clientId, clientPosts] of postsByClient) {
  const recipients = recipientsByClient.get(clientId) || [];

  if (recipients.length === 0) {
    // Per client, not global. This is pushed alongside the other clients' alerts
    // rather than returned early, so one client's misconfiguration cannot suppress
    // another client's alerts. If Notifications Ready routes it to the developer
    // chat on the false branch while the true branch still sends.
    out.push({ json: {
      notify_ready: false,
      scheduler_alert_type: 'NO_TELEGRAM_RECIPIENTS',
      client_id: clientId,
      client_name: clientNameById.get(clientId) || '',
      post_count: clientPosts.length,
      post_ids: clientPosts.map(post => String(post.postId || '')).filter(Boolean),
      message: 'Scheduled tracking generated ' + clientPosts.length +
        ' negative alert post(s) for ' + describeClient(clientId) +
        ', but that client has no active "Client Members" row with receives_alerts.' +
        ' Those alerts were not sent. Other clients were unaffected.',
    } });
    continue;
  }

  for (const recipient of recipients) {
    clientPosts.forEach((post, index) => {
      out.push(buildAlert(clientId, recipient, post, index));
    });
  }
}

return out;

const data = $json || {};
// T3: NO_TELEGRAM_RECIPIENTS is raised per client now, so the alert has to say
// which client is misconfigured -- a bare count is unactionable past one client.
const clientLine = (data.client_id || data.client_name)
  ? 'Client: ' + [data.client_name, data.client_id].filter(Boolean).join(' ')
  : '';
const message = ['<b>XMonitor staging handled error</b>','Workflow: Scheduled Post Tracking Staging',`Path: ${data.scheduler_alert_type || 'scheduler validation'}`,clientLine,`Reason: ${data.message || 'Scheduler stopped before sending alerts.'}`,data.post_count !== undefined ? `Post count: ${data.post_count}` : '',Array.isArray(data.post_ids) && data.post_ids.length ? `Posts: ${data.post_ids.slice(0, 20).join(', ')}` : ''].filter(Boolean).join('\n');
return [{ json: { developer_chat_id: '8677383067', message } }];

const probe = $input.first()?.json ?? {};
const status = Number(probe.statusCode ?? probe.status ?? 0);
const body = (probe.body && typeof probe.body === 'object') ? probe.body : probe;
const apiError = (body && typeof body === 'object' && body.error && typeof body.error === 'object') ? body.error : {};

const code = String(apiError.code || apiError.type || '').toLowerCase();
const providerMessage = String(apiError.message || '').trim();

const CREDIT_CODES = ['insufficient_quota', 'credit_balance_exhausted', 'billing_hard_limit_reached', 'account_deactivated'];
const outOfCredits = CREDIT_CODES.includes(code)
  || /no credits remaining|exceeded your current quota|billing/i.test(providerMessage);
const rateLimited = !outOfCredits && (code === 'rate_limit_exceeded' || status === 429);
const providerHealthy = status >= 200 && status < 300;

let post_count = 0;
let post_ids = [];
try {
  const parsed = JSON.parse($('Attach replies to posts').first()?.json?.text || '{}');
  const results = Array.isArray(parsed.results) ? parsed.results : [];
  post_count = results.length;
  post_ids = results.map(post => String(post.postId || '')).filter(Boolean);
} catch (e) {
  // leave defaults; the alert is still worth sending
}

const suffix = 'Sentiment analysis was aborted before any posts or replies were stored, and no negative-sentiment alerts were sent.';

let scheduler_alert_type;
let message;

if (outOfCredits) {
  scheduler_alert_type = 'SENTIMENT_NO_OPENAI_CREDITS';
  message = `OpenAI credits exhausted. ${suffix} Add credits at platform.openai.com billing to resume tracking. Provider said: ${providerMessage || code || 'insufficient quota'}`;
} else if (rateLimited) {
  scheduler_alert_type = 'SENTIMENT_RATE_LIMITED';
  message = `OpenAI rate limit hit (HTTP ${status || 429}). ${suffix} This usually clears on the next hourly pass. Provider said: ${providerMessage || code || 'rate limited'}`;
} else if (providerHealthy) {
  scheduler_alert_type = 'SENTIMENT_API_FAILED';
  message = `Sentiment analysis failed even though OpenAI is reachable and funded (probe returned HTTP ${status}). ${suffix} Likely a timeout or a malformed model response - check the execution for details.`;
} else {
  scheduler_alert_type = 'SENTIMENT_API_FAILED';
  message = `Sentiment analysis failed${status ? ` (probe returned HTTP ${status})` : ''}. ${suffix} Provider said: ${providerMessage || code || 'no reason returned'}`;
}

return [{
  json: {
    scheduler_alert_type,
    message,
    post_count,
    post_ids,
  },
}];

const MAX_MEDIA_REPLIES_PER_PASS = 40;

const source = $('Attach replies to posts').first()?.json || {};
const mediaReplies = Array.isArray(source.media_replies) ? source.media_replies : [];

const SYSTEM = [
  'You are a lebanese arabic sentiment labeling engine.',
  '',
  'You will be given ONE post and ONE reply to it. The reply has one or more images attached, and those images are provided to you directly.',
  '',
  'Label the sentiment of the reply toward the post and its author. Use exactly one of: Positive, Negative, Neutral.',
  '',
  'Return valid JSON only, in exactly this shape:',
  '{"sentiment": "Negative"}',
  '',
  'Rules:',
  '- Judge the reply on its text AND the attached images together.',
  '- A reply whose text is empty, very short, or just a mention plus a link can still be Negative when the image mocks, insults, ridicules or demeans the author of the post. This is the main case images exist to catch.',
  '- Any text inside an image (a screenshot, or a captioned meme) is part of the reply content. Read it.',
  '- Images must not soften the text. If the reply text alone already justifies Negative, an ordinary or harmless-looking image does not change that.',
  '- If the only image is a video thumbnail with no legible text and nothing clearly hostile, it is not evidence. Fall back to what the reply text supports.',
  '',
  'ATTRIBUTION IS DECISIVE. You are labeling sentiment toward the post and its author only. Before labeling, work out WHO the hostility in the image is aimed at:',
  '- Hostility counts as Negative ONLY when its target is the author of the post, the author\'s family, or the position the author is taking.',
  '- Hostility aimed at any OTHER person or institution - a rival politician, a president, an army, a party, a journalist, an unnamed group - is NOT Negative toward the author, even when the image is angry, accusatory, or insulting in tone. A reply that merely forwards someone else\'s accusation against a third party, and does not turn it on the author, is Neutral.',
  '- An image attacking a third party that the post ITSELF criticises means the reply is siding WITH the author: label it Positive, or Neutral if it shows no clear stance toward the author.',
  '- An image that flatters or DEFENDS a third party the post criticises IS Negative toward the author, because it dismisses the post and its argument.',
  '- Do not label Negative merely because the image contains angry or insulting language. Identify the target first.',
  '',
  '- Do not include explanations. Output JSON only.'
].join('\n');

if (mediaReplies.length === 0) {
  return [{ json: { no_media: true, media_reply_count: 0 } }];
}

const selected = mediaReplies.slice(0, MAX_MEDIA_REPLIES_PER_PASS);
const skipped = mediaReplies.length - selected.length;

const out = [];
for (const r of selected) {
  const content = [{
    type: 'text',
    text: 'POST by the monitored account:\n' + String(r.postText || '') + '\n\nREPLY to label:\n' + String(r.replyText || '')
  }];
  for (const url of (r.imageUrls || [])) {
    content.push({ type: 'image_url', image_url: { url: url, detail: 'low' } });
  }

  out.push({
    json: {
      no_media: false,
      reply_id: String(r.reply_id),
      post_id: String(r.post_id || ''),
      image_count: (r.imageUrls || []).length,
      skipped_over_cap: skipped,
      body: {
        model: 'gpt-5.4-mini',
        temperature: 0,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: SYSTEM },
          { role: 'user', content: content }
        ]
      }
    }
  });
}

return out;

function parseResults(item) {
  const candidates = [
    item.json?.output?.[0]?.content?.[0]?.text,
    item.json?.output,
    item.json?.text,
  ];

  for (const candidate of candidates) {
    let value = candidate;
    if (typeof value === 'string') {
      try {
        value = JSON.parse(value);
      } catch {
        continue;
      }
    }

    if (Array.isArray(value?.results)) {
      return value.results;
    }
  }

  throw new Error('OpenAI response did not contain a results array.');
}

const results = $('Analyze Sentiment with ChatGPT').all().flatMap(item => parseResults(item));

let requests = [];
let responses = [];
try { requests = $('Build Media Classify Requests').all(); } catch (e) { requests = []; }
// Not executed on a pass with no media replies.
try { responses = $('Classify Media Replies').all(); } catch (e) { responses = []; }

const VALID = new Set(['Positive', 'Negative', 'Neutral']);
const overrides = new Map();
let applied = 0;
let failed = 0;

for (let i = 0; i < requests.length; i++) {
  const req = requests[i].json || {};
  if (req.no_media) continue;

  const res = responses[i] ? responses[i].json : null;
  let label = '';
  try {
    const raw = (res && res.choices && res.choices[0] && res.choices[0].message)
      ? res.choices[0].message.content
      : null;
    if (raw) {
      const parsed = (typeof raw === 'string') ? JSON.parse(raw) : raw;
      label = String(parsed.sentiment || '');
    }
  } catch (e) {
    label = '';
  }

  if (VALID.has(label)) {
    overrides.set(String(req.reply_id), label);
    applied += 1;
  } else {
    // Degrade to the text-only label rather than dropping the reply.
    failed += 1;
  }
}

let changed = 0;
for (const post of results) {
  for (const reply of (post.replies || [])) {
    const override = overrides.get(String(reply.id));
    if (!override) continue;
    if (String(reply.sentiment || '') !== override) changed += 1;
    reply.sentiment = override;
    reply.media_labeled = true;
  }
}

return [{
  json: {
    text: JSON.stringify({ results }),
    media_labels_applied: applied,
    media_labels_failed: failed,
    media_labels_changed_from_text: changed,
  },
}];

const data = $json || {};
const which = [
  data.replies_truncated ? 'replies' : null,
  data.posts_truncated ? 'posts' : null,
].filter(Boolean).join(' and ');

return [{
  json: {
    scheduler_alert_type: 'SEARCH_PAGE_CAP_REACHED',
    message: `X ${which} search stopped on the page cap with a next_token still pending, so this pass did not read everything available. `
      + `Reply pages fetched: ${data.reply_page_count ?? 0}; post pages fetched: ${data.post_page_count ?? 0}; `
      + `replies returned: ${data.fetched_reply_count ?? 0}. `
      + 'Because the replies query is incremental, the unread replies are NOT re-requested on the next pass - the run state has already moved past them. '
      + 'Raise maxRequests on the affected node and re-run a backfill with a null Run State watermark.',
    post_count: Array.isArray(data.candidate_post_ids) ? data.candidate_post_ids.length : 0,
    post_ids: Array.isArray(data.candidate_post_ids) ? data.candidate_post_ids : [],
  },
}];

// Reached when a pass ends early with nothing to analyze. Three ways in:
//   - no active tracked users            (If Scheduler Should Continue, false branch)
//   - the posts search returned nothing  (filter sees no items)
//   - no post cleared the 10-reply filter
// All three are successful passes that found no work, so the watermark should
// advance - otherwise a quiet stretch strands it and the next active run pays for
// the whole 7-day fallback window.
//
// The exception is a truncated posts search: a qualifying post may sit on a page we
// never read, so advancing past it would skip those replies permanently. Cost is
// recoverable, missed replies are not, so truncation wins.

function lastPageStillHasToken(pages) {
  const byChunk = new Map();
  pages.forEach((page) => {
    let key = 'unknown';
    const paired = page.pairedItem;
    if (typeof paired === 'number') key = String(paired);
    else if (paired && typeof paired === 'object' && paired.item !== undefined) key = String(paired.item);
    if (!byChunk.has(key)) byChunk.set(key, []);
    byChunk.get(key).push(page);
  });
  for (const group of byChunk.values()) {
    const last = group[group.length - 1];
    if (last?.json?.meta?.next_token) return true;
  }
  return false;
}

let reason = 'NO_QUALIFYING_POSTS';
let postPageCount = 0;
let postsTruncated = false;

try {
  const postPages = $('Get posts of tracked users').all();
  postPageCount = postPages.length;
  postsTruncated = lastPageStillHasToken(postPages);
  const returnedAny = postPages.some(page => (page.json?.data || []).length > 0);
  if (!returnedAny) reason = 'NO_POSTS_RETURNED';
} catch (e) {
  // The posts node never ran, so this is the no-tracked-users pass.
  reason = 'NO_TRACKED_USERS';
}

return [{
  json: {
    quiet_reason: reason,
    post_page_count: postPageCount,
    posts_truncated: postsTruncated,
    fetch_truncated: postsTruncated,
    has_new_replies: false,
    new_reply_count: 0,
  },
}];

// One OpenAI call per client, so each call carries only that client's rules.
// Stance rules are client-specific; leaking one client's rules into another
// client's replies would actively degrade labelling. With a single configured
// client this emits exactly one batch - identical to the previous single call.

const payloadRaw = $('Attach replies to posts').first()?.json?.text || '{"results":[]}';
let allPosts = [];
try {
  const parsed = JSON.parse(payloadRaw);
  allPosts = Array.isArray(parsed.results) ? parsed.results : [];
} catch {
  allPosts = [];
}

// X author id -> client_id, from the tracked users this run already fetched.
const clientByAuthorId = new Map(
  $('Get Tracked Users').all().map(item => [
    String(item.json.user_id || ''),
    String(item.json.client_id || ''),
  ])
);

// Get Active Cheat Sheets uses alwaysOutputData, so an empty table still yields
// one blank item. Drop anything without both a client and rule text.
const sheetByClientId = new Map(
  $('Get Active Cheat Sheets').all()
    .map(item => item.json || {})
    .filter(row => row.client_id && row.rules_text)
    .map(row => [
      String(row.client_id),
      { version: Number(row.version || 0), rulesText: String(row.rules_text) },
    ])
);

const batches = new Map();
for (const post of allPosts) {
  const clientId = clientByAuthorId.get(String(post.userId || '')) || 'unknown';
  if (!batches.has(clientId)) batches.set(clientId, []);
  batches.get(clientId).push(post);
}

// Nothing to score. Returning no items stops the analysis branch cleanly rather
// than paying OpenAI for an empty results array.
if (batches.size === 0) return [];

return [...batches.entries()].map(([clientId, posts]) => {
  const sheet = sheetByClientId.get(clientId);
  const block = sheet
    ? `Client-specific labelling rules (cheat sheet v${sheet.version}). Apply these over your general judgement whenever they match:\n${sheet.rulesText}`
    : 'No client-specific labelling rules are configured for this client. Use your general judgement.';

  const replyCount = posts.reduce(
    (sum, post) => sum + (Array.isArray(post.replies) ? post.replies.length : 0),
    0
  );

  return {
    json: {
      client_id: clientId,
      cheat_sheet_version: sheet ? sheet.version : 0,
      cheat_sheet_block: block,
      post_count: posts.length,
      reply_count: replyCount,
      text: JSON.stringify({ results: posts }),
    },
  };
});
